CREATE TABLE "fx_currencies" ("company_id" TEXT NOT NULL, "code" TEXT NOT NULL, "precision" INTEGER NOT NULL, "is_base" BOOLEAN NOT NULL DEFAULT false, "status" TEXT NOT NULL DEFAULT 'ACTIVE', CONSTRAINT "fx_currencies_pkey" PRIMARY KEY ("company_id","code"), CONSTRAINT "fx_currencies_precision_check" CHECK ("precision" BETWEEN 0 AND 9));
CREATE UNIQUE INDEX "fx_one_base_currency_per_company" ON "fx_currencies"("company_id") WHERE "is_base" = true;
CREATE TABLE "fx_rates" ("id" TEXT NOT NULL, "company_id" TEXT NOT NULL, "from_currency" TEXT NOT NULL, "to_currency" TEXT NOT NULL, "effective_at" TIMESTAMP(3) NOT NULL, "rate" DECIMAL(38,18) NOT NULL, "source" TEXT NOT NULL, CONSTRAINT "fx_rates_pkey" PRIMARY KEY ("id"), CONSTRAINT "fx_rates_positive_check" CHECK ("rate" > 0), CONSTRAINT "fx_rates_distinct_currency_check" CHECK ("from_currency" <> "to_currency"));
CREATE UNIQUE INDEX "fx_rates_company_id_from_currency_to_currency_effective_at_key" ON "fx_rates"("company_id","from_currency","to_currency","effective_at");
CREATE INDEX "fx_rates_lookup_idx" ON "fx_rates"("company_id","from_currency","to_currency","effective_at");
CREATE TABLE "cba_cost_centers" ("id" TEXT NOT NULL, "company_id" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ACTIVE', "parent_id" TEXT, CONSTRAINT "cba_cost_centers_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "cba_cost_centers_company_id_code_key" ON "cba_cost_centers"("company_id","code");
CREATE UNIQUE INDEX "cba_cost_centers_company_id_id_key" ON "cba_cost_centers"("company_id","id");
CREATE INDEX "cba_cost_centers_company_id_status_idx" ON "cba_cost_centers"("company_id","status");
ALTER TABLE "cba_cost_centers" ADD CONSTRAINT "cba_cost_centers_parent_fkey" FOREIGN KEY ("company_id", "parent_id") REFERENCES "cba_cost_centers"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "cba_program_cost_centers" ("company_id" TEXT NOT NULL, "source_type" TEXT NOT NULL, "source_id" TEXT NOT NULL, "cost_center_id" TEXT NOT NULL, CONSTRAINT "cba_program_cost_centers_pkey" PRIMARY KEY ("company_id","source_type","source_id"), CONSTRAINT "cba_program_cost_centers_cost_center_fkey" FOREIGN KEY ("company_id", "cost_center_id") REFERENCES "cba_cost_centers"("company_id", "id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "cba_program_cost_centers_company_id_cost_center_id_idx" ON "cba_program_cost_centers"("company_id","cost_center_id");
